package vn.nanase.hako.tests;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import vn.nanase.hako.*;
public final class BatchWorkflowTest extends Instrumentation {
 int checks;void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);Bundle b=new Bundle();b.putString("stream","PASS "+label+"\n");sendStatus(0,b);}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();try{Context ctx=getTargetContext();Diagnostics.start(ctx);Store s=Store.get(ctx);ctx.getSharedPreferences("settings",0).edit().putString("origin","https://invalid.example").putBoolean("charging",false).putBoolean("sync_paused",false).commit();HakoParser.ORIGIN="https://invalid.example";String book="truyen-999010",base="https://invalid.example/truyen/999010-fixture";s.putBook(new HakoParser.Link(book,"Batch fixture",base));s.visited(book);s.pin(book,true);s.setKeepFull(book,true);List<HakoParser.Link> links=new ArrayList<>();List<String> text=new ArrayList<>();for(int n=1;n<=38;n++){boolean art=n==3||n==9||n==18;String id=book+"-"+n;links.add(new HakoParser.Link(id,art?"Tập 1 · Minh họa":"Tập 1 · Chương "+n,base+"/c"+n+"-fixture"));if(!art)text.add(id);}s.catalog(book,links);s.position(book,text.get(0),0,0);Store.BatchPlan first=s.readingBatch(s.book(book),s.chapters(book));check(first.chapters.size()==15&&first.chapters.get(14).id.equals(text.get(14)),"Batch counts fifteen text chapters despite interleaved illustrations");for(Store.Chapter ch:first.chapters){Store.write(s.html(ch.id),"<p>Nội dung đã lưu hợp lệ.</p>");s.state(ch.id,true,"");}check(!s.needsReadingDownload(book)&&s.batchDone(book,first),"Validated full batch sleeps even for favorite and retained-full book");OperationTrace.Span gate=OperationTrace.begin("test.batch_gate");for(int n=1;n<13;n++){s.position(book,text.get(n),0,0);check(!s.needsReadingDownload(book),"Opening chapter before fourteen does not extend batch "+n);}OperationTrace.end(gate,"ok",0);check(OperationTrace.payload().getJSONObject("totals").getJSONArray("test.batch_gate").getLong(10)==0,"Completed batch does not rescan chapter files at every open");s.position(book,text.get(13),0,0);Store.BatchPlan second=s.readingBatch(s.book(book),s.chapters(book));check(second.chapters.get(0).id.equals(text.get(15))&&second.chapters.size()==15,"Fourteenth text chapter activates the next nonoverlapping batch");check(s.needsReadingDownload(book),"New batch contains genuinely missing chapters");Store.write(s.html(second.chapters.get(4).id),"<p>Đã tải một chương ở giữa.</p>");s.state(second.chapters.get(4).id,true,"");Store.BatchPlan resumed=s.readingBatch(s.book(book),s.chapters(book));check(resumed.key.equals(second.key)&&s.readable(second.chapters.get(4).id),"Interrupted batch keeps membership and reuses middle cached chapter");s.resetDerived();check(s.readingBatch(s.book(book),s.chapters(book)).key.equals(second.key),"Batch anchor survives metadata cache reset");s.position(book,text.get(28),0,0);Store.BatchPlan tail=s.readingBatch(s.book(book),s.chapters(book));check(tail.chapters.size()==5&&tail.chapters.get(0).id.equals(text.get(30)),"Last batch includes only available remaining text");s.completeThrough(book,text.get(text.size()-1));s.queueCaughtUp(book);check(s.queued(book),"Completion initially waits for server availability");String shelf="<table><tr><td><a href='"+base+"'>Batch fixture</a></td></tr></table>";ReadSync.observeShelf(ctx,shelf);check(!s.queued(book),"Verified shelf row without read-all button removes pending request");s.queueCaughtUp(book);check(!s.queued(book),"Same completion does not recreate missing-button pending");ReadSync.observeShelf(ctx,"<input type='password'>"+shelf);check(!s.queued(book),"Login page cannot change missing-button state");ReadSync.observeShelf(ctx,"<table><tr><td><a href='"+base+"'>Batch fixture</a></td><td><a class='mark-read' data-series='999010' data-unread='1'>Đọc hết</a></td></tr></table>");s.queueCaughtUp(book);check(s.queued(book),"Observed return of read-all button permits a new request");ctx.getSharedPreferences("settings",0).edit().putLong("cooldownUntil",System.currentTimeMillis()+1800000).commit();Repository.allowed(ctx);check(!ctx.getSharedPreferences("settings",0).contains("cooldownUntil"),"Old thirty-minute lock is removed and retry allowed immediately");Repository.cooldown(ctx,1800000);Repository.allowed(ctx);check(!ctx.getSharedPreferences("settings",0).contains("cooldownUntil"),"Access failure cannot install a new thirty-minute lock");s.noReadButton(book);ctx.getSharedPreferences("settings",0).edit().putBoolean("sync_paused",true).commit();LibraryState.refresh(ctx);MainActivity activity=(MainActivity)startActivitySync(new Intent().setClassName(ctx.getPackageName(),"vn.nanase.hako.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();java.lang.reflect.Method mark=MainActivity.class.getDeclaredMethod("markCaughtUp",Store.Book.class);mark.setAccessible(true);Store.Book selected=s.book(book);runOnMainSync(()->{try{mark.invoke(activity,selected);}catch(Exception e){throw new RuntimeException(e);}});java.lang.reflect.Field statusField=MainActivity.class.getDeclaredField("status");statusField.setAccessible(true);long limit=SystemClock.elapsedRealtime()+5000;while(SystemClock.elapsedRealtime()<limit){waitForIdleSync();android.widget.TextView status=(android.widget.TextView)statusField.get(activity);if(status!=null&&status.getText().toString().equals("Không chờ gửi HAKO"))break;SystemClock.sleep(25);}check(!s.queued(book)&&((android.widget.TextView)statusField.get(activity)).getText().toString().equals("Không chờ gửi HAKO"),"Manual read-all UI cannot claim pending when missing button suppressed the queue");runOnMainSync(()->activity.finish());result.putString("stream","PASS TOTAL "+checks+" batch workflow checks\n");finish(0,result);}catch(Throwable error){result.putString("stream","FAIL "+error+"\n");finish(1,result);}}
}

